import {reservationStatus,type CancellationDisposition} from '@/lib/reservation-status';
import type {ReportCell} from '@/lib/report-export';
export type NoShowCommand={p_request:string;p_reservation:string;p_expected_source_version:number;p_expected_business_date:string;p_reason:string};
export type NoShowResult={request_id:string;reservation_id:string;status:'Cancelled';cancellation_disposition:'no_show';recorded_at:string;business_date:string;source_version:number;capacity_configuration_changed:false;current_future_inventory_released_units:0;fees_changed:false;folio_changed:false;financial_review_required:boolean;financial_handling:'separate_review';replayed:boolean};
export type NoShowStatus={found:boolean;action?:string;result?:NoShowResult};
export type NoShowPreview=CancellationDisposition&{reservation_id:string;status:string;source:string;source_version:number;arrival:string|null;departure:string|null;business_date:string;eligible:boolean;blockers:string[];folio_available:boolean;opening_mode:'frozen'|'reservation_preview'|'unavailable';charges_minor:number|null;recorded_paid_minor:number|null;balance_minor:number|null;financial_review_required:boolean;financial_handling:'separate_review';service_warning:string;late_arrival_policy:string;generated_at:string};
export type NoShowReport={property:{id:string;name:string;time_zone:string};period:{start:string;end:string;end_exclusive:true;basis:'scheduled_arrival'};generated_at:string;count:number;rows_truncated:false;definition:string;rows:(CancellationDisposition&{reservation_id:string;source:string;source_booking_id:string;status:string;arrival:string;departure:string;recorded_by:string;reason:string;request_id:string})[]};
const uuid=(x:unknown)=>typeof x==='string'&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(x);
const civilDate=(x:unknown)=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x))&&new Date(x).toISOString().slice(0,10)===x;
export const noShowKey=(actor:string,tenant:string,property:string,reservation:string)=>'iratepilot-pms-pending-no-show:'+actor+':'+tenant+':'+property+':'+reservation;
export function validateNoShowPreview(value:unknown,reservation:string):NoShowPreview{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('The no-show review could not be verified. Refresh before continuing.');
 const p=value as NoShowPreview;
 if(p.reservation_id!==reservation||!uuid(p.reservation_id)||!Number.isSafeInteger(p.source_version)||p.source_version<1||!civilDate(p.business_date)||typeof p.eligible!=='boolean'||!Array.isArray(p.blockers)||!p.blockers.every(b=>typeof b==='string')||typeof p.status!=='string'||typeof p.source!=='string'||![p.charges_minor,p.recorded_paid_minor,p.balance_minor].every(a=>a===null||Number.isSafeInteger(a))||!['frozen','reservation_preview','unavailable'].includes(p.opening_mode)||p.financial_handling!=='separate_review')throw Error('The no-show review could not be verified. Refresh before continuing.');
 if(p.eligible&&(p.status!=='Confirmed'||!['direct','migration'].includes(p.source)||p.blockers.length!==0||!civilDate(p.arrival)||!civilDate(p.departure)||p.departure!<=p.arrival!||p.business_date<p.departure!))throw Error('The no-show eligibility response is inconsistent. Refresh before continuing.');
 return p;
}
export function validNoShow(value:unknown,reservation:string):value is NoShowCommand{if(!value||typeof value!=='object'||Array.isArray(value))return false;const p=value as NoShowCommand;return Object.keys(p).sort().join(',')==='p_expected_business_date,p_expected_source_version,p_reason,p_request,p_reservation'&&uuid(p.p_request)&&p.p_reservation===reservation&&uuid(p.p_reservation)&&Number.isSafeInteger(p.p_expected_source_version)&&p.p_expected_source_version>0&&civilDate(p.p_expected_business_date)&&typeof p.p_reason==='string'&&p.p_reason===p.p_reason.trim()&&p.p_reason.length>=4&&p.p_reason.length<=500&&!Array.from(p.p_reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)}
export function validateNoShowReceipt(status:NoShowStatus,p:NoShowCommand){const r=status.result;if(!status.found||status.action!=='mark_no_show'||!r||r.request_id!==p.p_request||r.reservation_id!==p.p_reservation||r.source_version!==p.p_expected_source_version||r.business_date!==p.p_expected_business_date||r.status!=='Cancelled'||r.cancellation_disposition!=='no_show'||r.fees_changed!==false||r.folio_changed!==false||r.capacity_configuration_changed!==false||r.current_future_inventory_released_units!==0||r.financial_handling!=='separate_review'||typeof r.recorded_at!=='string'||!Number.isFinite(Date.parse(r.recorded_at)))throw Error('The saved no-show receipt does not match this request. Reconcile the reservation before continuing.')}
export const noShowBlockers:Record<string,string>={source_owned_ota:'This OTA reservation must be handled through its source.',not_confirmed:'Only Confirmed reservations can receive a new no-show disposition.',stay_has_started:'A stay with check-in or checkout history cannot be marked as a no-show.',stay_dates_unavailable:'The scheduled stay dates are unavailable.',late_arrival_window_open:'The late-arrival window remains open until the scheduled departure date.'};
export const noShowHeaders=['Reservation','Source','Source booking reference','Disposition','Scheduled arrival','Scheduled departure','No show recorded at','Recorded by','Review reason','Request'];
export function noShowRows(report:NoShowReport):ReportCell[][]{return report.rows.map(r=>[r.reservation_id,r.source,r.source_booking_id,reservationStatus(r),r.arrival,r.departure,r.no_show_recorded_at,r.recorded_by,r.reason,r.request_id])}
